<?php
require_once __DIR__.'/_layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(($_POST['action']??'')==='delete'){$s=$pdo->prepare('DELETE FROM restaurant_menu WHERE item_id=?');$s->execute([(int)$_POST['id']]);flash('success','Menu item deleted.');redirect('restaurant.php');}$name=trim($_POST['item_name']??'');$category=trim($_POST['category']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$image=trim($_POST['image']??'');$available=isset($_POST['availability'])?1:0;if($name&&$category&&$price>0&&filter_var($image,FILTER_VALIDATE_URL)){$id=(int)($_POST['id']??0);if($id){$s=$pdo->prepare('UPDATE restaurant_menu SET item_name=?,category=?,description=?,price=?,image=?,availability=? WHERE item_id=?');$s->execute([$name,$category,$description,$price,$image,$available,$id]);}else{$s=$pdo->prepare('INSERT INTO restaurant_menu(item_name,category,description,price,image,availability) VALUES(?,?,?,?,?,?)');$s->execute([$name,$category,$description,$price,$image,$available]);}flash('success','Menu saved.');redirect('restaurant.php');}}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM restaurant_menu WHERE item_id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$items=$pdo->query('SELECT * FROM restaurant_menu ORDER BY category,item_name')->fetchAll();admin_start('At the table');?><div class="panel"><h2><?= $edit?'Edit dish':'Add a dish' ?></h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($edit['item_id']??0) ?>"><div class="form-grid"><div class="form-field"><label>Dish name</label><input name="item_name" required value="<?= e($edit['item_name']??'') ?>"></div><div class="form-field"><label>Category</label><input name="category" required placeholder="Mains, Dessert…" value="<?= e($edit['category']??'') ?>"></div><div class="form-field"><label>Price (₹)</label><input type="number" name="price" min="1" value="<?= e($edit['price']??'') ?>" required></div><div class="form-field"><label>Image URL</label><input type="url" name="image" value="<?= e($edit['image']??'') ?>" required></div><div class="form-field wide"><label>Description</label><textarea name="description"><?= e($edit['description']??'') ?></textarea></div><div class="form-field"><label><input type="checkbox" name="availability" <?= !isset($edit)||$edit['availability']?'checked':'' ?>> Available</label></div></div><button class="button">Save dish</button></form></div><table class="data-table" style="margin-top:25px"><thead><tr><th>Dish</th><th>Category</th><th>Price</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['item_name']) ?></td><td><?= e($i['category']) ?></td><td>₹<?= number_format((float)$i['price']) ?></td><td><?= $i['availability']?'Available':'Hidden' ?></td><td><a href="?edit=<?= (int)$i['item_id'] ?>">Edit</a> · <form style="display:inline" method="post" onsubmit="return confirm('Delete this dish?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$i['item_id'] ?>"><button style="border:0;background:none;color:#965d4e;cursor:pointer">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php admin_end(); ?>
